package jit

import (
	"encoding/base64"
	"fmt"
	"path/filepath"
	"reflect"
	"runtime"
	"sort"
	"sync"

	"cmd/compile/publicinternal/jitmeta"
)

// BuildMetadata is the decoded compiler and package context generated by the
// Go compiler for a package that imports jit.
type BuildMetadata = jitmeta.BuildMetadata

// PackageExport contains the compiler export data and archive for one
// build-selected package.
type PackageExport = jitmeta.PackageExport

// LinkKind identifies the kind of Go object retained by a link reference.
type LinkKind string

const (
	FunctionLink LinkKind = "function"
	VariableLink LinkKind = "variable"
	TypeLink     LinkKind = "type"
)

// LinkReference is emitted into the host package as an ordinary Go reference.
// Value therefore creates a normal linker relocation that keeps the object
// reachable in the final executable.
type LinkReference struct {
	PackagePath string
	Name        string
	Kind        LinkKind
	Value       any
}

// LinkedSymbol describes a resolved function, package variable, or runtime
// type descriptor in the final executable.
type LinkedSymbol struct {
	PackagePath string
	Name        string
	Kind        LinkKind
	Address     uintptr
	PC          uintptr
	Type        reflect.Type
	Value       any
}

// LinkMetadata contains runtime-resolved addresses for symbols retained by
// the final Go linker.
type LinkMetadata struct {
	Symbols []LinkedSymbol
}

// Metadata contains decoded compiler metadata and linker-resolved symbols for
// one host package. Treat its exported slices as read-only. Values for
// VariableLink symbols point at the package's live mutable storage.
type Metadata struct {
	Build BuildMetadata
	Link  LinkMetadata
}

var metadataRegistry = struct {
	sync.RWMutex
	byPackage map[string]*Metadata
}{byPackage: make(map[string]*Metadata)}

// TypeFor returns the runtime type descriptor for T. It is also used by the
// compiler-generated link table to keep named package types reachable.
func TypeFor[T any]() reflect.Type {
	return reflect.TypeOf((*T)(nil)).Elem()
}

// RegisterBuildMetadata decodes the compiler-generated bundle and resolves its
// relocation-backed references. It is called from an init function inserted
// by cmd/compile; malformed metadata is a binary/toolchain consistency error.
func RegisterBuildMetadata(encoded string, refs []LinkReference) {
	data, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		panic(fmt.Errorf("jit: decode embedded metadata: %w", err))
	}
	bundle, err := jitmeta.Unmarshal(data)
	if err != nil {
		panic(fmt.Errorf("jit: read embedded metadata: %w", err))
	}
	if bundle.Build.GOOS != runtime.GOOS || bundle.Build.GOARCH != runtime.GOARCH {
		panic(fmt.Errorf("jit: metadata target %s/%s does not match executable %s/%s", bundle.Build.GOOS, bundle.Build.GOARCH, runtime.GOOS, runtime.GOARCH))
	}

	declared := make(map[string]jitmeta.Symbol, len(bundle.Link.Symbols))
	for _, symbol := range bundle.Link.Symbols {
		declared[symbolKey(symbol.PackagePath, symbol.Name, LinkKind(symbol.Kind))] = symbol
	}
	resolved := make([]LinkedSymbol, 0, len(refs))
	seen := make(map[string]bool, len(refs))
	for _, ref := range refs {
		key := symbolKey(ref.PackagePath, ref.Name, ref.Kind)
		if _, ok := declared[key]; !ok {
			panic(fmt.Errorf("jit: link reference %s.%s is absent from compiler metadata", ref.PackagePath, ref.Name))
		}
		if seen[key] {
			panic(fmt.Errorf("jit: duplicate link reference %s.%s", ref.PackagePath, ref.Name))
		}
		seen[key] = true
		symbol, err := resolveLinkReference(ref)
		if err != nil {
			panic(err)
		}
		resolved = append(resolved, symbol)
	}
	if len(seen) != len(declared) {
		panic(fmt.Errorf("jit: linker emitted %d references for %d metadata symbols", len(seen), len(declared)))
	}

	metadata := &Metadata{Build: bundle.Build, Link: LinkMetadata{Symbols: resolved}}
	metadataRegistry.Lock()
	defer metadataRegistry.Unlock()
	if _, exists := metadataRegistry.byPackage[bundle.Build.PackagePath]; exists {
		panic(fmt.Errorf("jit: metadata already registered for package %q", bundle.Build.PackagePath))
	}
	metadataRegistry.byPackage[bundle.Build.PackagePath] = metadata
}

// MetadataFor returns the metadata registered for packagePath.
func MetadataFor(packagePath string) (*Metadata, bool) {
	metadataRegistry.RLock()
	defer metadataRegistry.RUnlock()
	m, ok := metadataRegistry.byPackage[packagePath]
	return m, ok
}

// RegisteredMetadata returns the metadata bundles registered in this binary,
// sorted by package import path. It returns a snapshot of the registry slice;
// each Metadata value describes one package that directly imported jit.
func RegisteredMetadata() []*Metadata {
	metadataRegistry.RLock()
	defer metadataRegistry.RUnlock()
	result := make([]*Metadata, 0, len(metadataRegistry.byPackage))
	for _, metadata := range metadataRegistry.byPackage {
		result = append(result, metadata)
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i].Build.PackagePath < result[j].Build.PackagePath
	})
	return result
}

// LookupSymbol returns a linked symbol by its package path and Go name.
func (m *Metadata) LookupSymbol(packagePath, name string) (LinkedSymbol, bool) {
	if m == nil {
		return LinkedSymbol{}, false
	}
	for _, symbol := range m.Link.Symbols {
		if symbol.PackagePath == packagePath && symbol.Name == name {
			return symbol, true
		}
	}
	return LinkedSymbol{}, false
}

// ContextForFile returns the package name and imports recorded for one source
// file. name may be the recorded path or an unambiguous base name. Import scope
// in Go is file-local, so snippets should use the context of their eval site.
func (m *Metadata) ContextForFile(name string) (PackageContext, error) {
	if m == nil {
		return PackageContext{}, fmt.Errorf("jit: no metadata for source file %q", name)
	}
	var selected *jitmeta.File
	for i := range m.Build.Files {
		if m.Build.Files[i].Name == name {
			selected = &m.Build.Files[i]
			break
		}
	}
	if selected == nil {
		base := filepath.Base(name)
		for i := range m.Build.Files {
			if filepath.Base(m.Build.Files[i].Name) != base {
				continue
			}
			if selected != nil {
				return PackageContext{}, fmt.Errorf("jit: source file name %q is ambiguous; use its recorded path", name)
			}
			selected = &m.Build.Files[i]
		}
	}
	if selected == nil {
		return PackageContext{}, fmt.Errorf("jit: source file %q is not in package metadata", name)
	}
	imports := append([]Import(nil), selected.Imports...)
	return PackageContext{PackageName: m.Build.PackageName, Imports: imports}, nil
}

func resolveLinkReference(ref LinkReference) (LinkedSymbol, error) {
	symbol := LinkedSymbol{
		PackagePath: ref.PackagePath,
		Name:        ref.Name,
		Kind:        ref.Kind,
		Value:       ref.Value,
	}
	switch ref.Kind {
	case FunctionLink:
		value := reflect.ValueOf(ref.Value)
		if !value.IsValid() || value.Kind() != reflect.Func {
			return LinkedSymbol{}, fmt.Errorf("jit: %s.%s link value is not a function", ref.PackagePath, ref.Name)
		}
		symbol.PC = value.Pointer()
		symbol.Address = symbol.PC
		symbol.Type = value.Type()
	case VariableLink:
		value := reflect.ValueOf(ref.Value)
		if !value.IsValid() || value.Kind() != reflect.Pointer || value.IsNil() {
			return LinkedSymbol{}, fmt.Errorf("jit: %s.%s link value is not a non-nil variable pointer", ref.PackagePath, ref.Name)
		}
		symbol.Address = value.Pointer()
		symbol.Type = value.Type().Elem()
	case TypeLink:
		typ, ok := ref.Value.(reflect.Type)
		if !ok || typ == nil {
			return LinkedSymbol{}, fmt.Errorf("jit: %s.%s link value is not a reflect.Type", ref.PackagePath, ref.Name)
		}
		value := reflect.ValueOf(typ)
		if value.Kind() == reflect.Pointer {
			symbol.Address = value.Pointer()
		}
		symbol.Type = typ
	default:
		return LinkedSymbol{}, fmt.Errorf("jit: %s.%s has unknown link kind %q", ref.PackagePath, ref.Name, ref.Kind)
	}
	return symbol, nil
}

func symbolKey(packagePath, name string, kind LinkKind) string {
	return packagePath + "\x00" + name + "\x00" + string(kind)
}
